function __teamsTextFromCard(card) {
  const lines = [];
  if (card?.title) lines.push(String(card.title), '');
  for (const sec of (card?.sections || [])) {
    if (sec.text) lines.push(String(sec.text));
    if (sec.activityTitle) lines.push(String(sec.activityTitle).replace(/^\*\*|\*\*$/g, ''));
    if (Array.isArray(sec.facts)) {
      for (const f of sec.facts) lines.push('- **' + f.name + ':** ' + f.value);
    }
    lines.push('');
  }
  return lines.join('\n').trim();
}

function __teamsTextFromAdaptive(payload) {
  const content = payload?.attachments?.[0]?.content;
  if (!content) return String(payload?.text || payload?.title || 'Notificacion');
  const lines = [];
  const walk = (items) => {
    for (const item of items || []) {
      if (item.type === 'TextBlock' && item.text) lines.push(String(item.text));
      if (item.type === 'FactSet' && item.facts) {
        for (const f of item.facts) lines.push('- **' + f.title + ':** ' + f.value);
      }
      if (item.items) walk(item.items);
      if (item.columns) for (const col of item.columns) walk(col.items);
    }
  };
  walk(content.body);
  return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function __teamsTextFromPayload(o) {
  if (!o || typeof o !== 'object') return String(o ?? 'N/D');
  if (o.body?.text) return o.body.text;
  if (o['@type'] === 'MessageCard' || o.sections) return __teamsTextFromCard(o);
  if (o.type === 'message' && o.attachments) return __teamsTextFromAdaptive(o);
  return JSON.stringify(o, null, 2);
}

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}

// === Function – Build Teams payload (ALERTA AutoGrowth) ===
const P = $node["Set - Params"].json || {};
const j = $json;

const alerts = j.alerts || [];
if (!alerts.length) return [];

const tzOff = Number(P.tz_offset_hours || 0);
const toLocal = iso => {
  if (!iso) return "N/D";
  const d = new Date(iso);
  const offMs = tzOff * 3600 * 1000;
  return new Date(d.getTime() + offMs)
    .toISOString().replace("T"," ").substring(0,19);
};

const num  = v => (v == null ? null : Number(v));
const fmt2 = v => (Number.isFinite(num(v)) ? num(v).toFixed(2) : String(v ?? "N/D"));

const inst = j.instance_name || "N/D";

// ✅ Cada evento en una línea tipo lista markdown
const lines = alerts.map(r => {
  const g   = (r.growth_mb != null) ? fmt2(r.growth_mb) + " MB" : "N/D";
  const db  = r.database || "-";
  const file = r.file || "-";
  const est = r.estado || "-";
  const ts  = r.ts_sp ? toLocal(r.ts_sp) : "N/D";

  // Guion al inicio para que Teams lo vea como bullet
  return `- **BD:** ${db}  •  **Archivo:** ${file}  •  **Crec.:** ${g}  •  **Estado:** ${est}  •  **Fecha:** ${ts}`;
});

const diag = [
  "- Se detectaron eventos de **AutoGrowth** recientes en una o más bases de datos.",
  "- El AutoGrowth frecuente suele indicar crecimiento no planificado de archivos de datos o de log.",
  "- Puede provocar fragmentación, uso excesivo de disco y picos de latencia durante el crecimiento."
].join("\n");

const sugg = [
  "- Revisar tamaño inicial de los archivos de datos y log y ajustarlos a un valor más cercano al uso real.",
  "- Ajustar la configuración de AutoGrowth (evitar porcentajes muy pequeños o muy grandes; preferir MB fijos).",
  "- Revisar mantenimiento de índices y planes de crecimiento de la base de datos.",
  "- Validar que la unidad de disco tenga espacio suficiente y buen rendimiento (IOPS/latencia)."
].join("\n");

const title = `${P.title_prefix || "ALERTA – AutoGrowth"} • ${inst}`;

return {
  json: {
    "@type": "MessageCard",
    "@context": "https://schema.org/extensions",
    themeColor: "C0392B",
    summary: title,
    title,
    sections: [
      {
        markdown: true,
        text: `🔴 **ALERTA – AutoGrowth detectado**\n\nInstancia: **${inst}**\nEventos en esta ejecución: **${alerts.length}**\nHora local: ${toLocal(j.now_utc)}`
      },
      {
        markdown: true,
        text: `📄 **Detalle de eventos**\n\n${lines.join("\n")}`
      },
      {
        markdown: true,
        text: `📌 **Diagnóstico posible**\n${diag}`
      },
      {
        markdown: true,
        text: `✅ **Sugerencias**\n${sugg}`
      }
    ]
  }
};

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}

// === Function – Build Teams payload (RECOVERY) — AutoGrowth ===
const j = $json;

const recovered   = j.recovered_items || [];
const stillAlerts = j.alerts || [];

let title = "";
const lines = [];

// Global vs parcial
if (j.send_recovery_global) {
  title = "RECOVERY – AutoGrowth (todos OK)";
  lines.push(
    "Todos los archivos monitoreados por el SP `usp_MonitoreoAutogrowth` están ahora en estado **OK** (sin alertas de AutoGrowth)."
  );
} else {
  title = "RECOVERY parcial – AutoGrowth";
  lines.push(
    "Algunos archivos se han recuperado, pero aún quedan archivos en **ALERTA** por AutoGrowth."
  );
}

// Bloque de registros recuperados
if (recovered.length) {
  lines.push("");
  lines.push(`**Registros recuperados (${recovered.length}):**`);
  lines.push("");

  recovered.forEach(r => {
    const db    = r.BaseDeDatos || r.database || "N/D";
    const file  = r.Archivo     || r.file     || "N/D";
    const fecha = r.FechaHora   || r.ts_sp    || r.Fecha || r.fecha || "N/D";

    lines.push(`- **BD:** ${db}  •  **Archivo:** ${file}  •  Último evento en alerta: ${fecha}`);
  });
}

// Bloque de registros que siguen en alerta
if (stillAlerts.length) {
  lines.push("");
  lines.push(`**Registros que siguen en alerta (${stillAlerts.length}):**`);
  lines.push("");

  stillAlerts.forEach(r => {
    const db     = r.BaseDeDatos || r.database || "N/D";
    const file   = r.Archivo     || r.file     || "N/D";
    const estado = r.Estado      || r.estado   || "Alerta: AutoGrowth";

    lines.push(`- **BD:** ${db}  •  **Archivo:** ${file}  •  Estado actual: ${estado}`);
  });
}

const text = `### ${title}\n\n` + lines.join("\n");

// Recuerda: el HTTP manda {{ $json.body }}
return [
  {
    json: {
      body: {
        text,
      },
    },
  },
];

// === Function – Decidir estado (AutoGrowth) con recovery por registro ===

const P = $node["Set - Params"].json || {};

// 1) Filas actuales: tomamos las que ya procesaste en "Function – Expand filas"
//    (ajusta el nombre si el nodo se llama distinto)
const rows = $items("Function – Expand filas").map(i => i.json);

// Helper: ¿esta fila está en ALERTA?
const isAlert = (r) => {
  const e = String(r.estado || r.Estado || "").toUpperCase();
  return e.startsWith("ALERTA");   // "Alerta: AutoGrowth"
};

// Clasificación actual
const alerts = rows.filter(isAlert);
const oks    = rows.filter(r => !isAlert(r));

// 2) Estado global en memoria (staticData), igual que en el flujo Cron origin:blue
const staticData = $getWorkflowStaticData('global');

const last_state = staticData.last_state || "INIT";       // ALERT / OK / INIT
const state      = alerts.length > 0 ? "ALERT" : "OK";

staticData.last_state = state;

// Flags globales
const send_alert           = alerts.length > 0;
const send_recovery_global = (last_state === "ALERT" && state === "OK");

// 3) Recovery por registro (BaseDeDatos + Archivo)

staticData.items     = staticData.items || {};     // registros en alerta última vez
staticData.recovered = staticData.recovered || {}; // registros ya notificados como recovery

const prevItems    = staticData.items;
const recoveredMap = staticData.recovered;

// Clave única de cada registro de AutoGrowth
const getKey = (r) => {
  const db   = r.BaseDeDatos || r.database || "";
  const file = r.Archivo     || r.file     || "";
  return `${db}|${file}`;
};

// Conjunto actual de registros en alerta
const currentAlertSet = {};

for (const r of alerts) {
  const k = getKey(r);
  if (!k) continue;

  // Marca que sigue en alerta en esta corrida
  currentAlertSet[k] = true;

  // Guardamos la última fila en alerta
  prevItems[k] = r;

  // Si ya lo habíamos marcado como recuperado y volvió a alerta, limpiamos
  if (recoveredMap[k]) {
    delete recoveredMap[k];
  }
}

// Registros que se recuperaron en esta corrida:
// estaban en prevItems y YA NO aparecen en currentAlertSet.
const recovered_items = [];

for (const [k, lastRow] of Object.entries(prevItems)) {
  if (!currentAlertSet[k]) {
    // Solo enviamos recovery si aún no lo habíamos enviado para este registro
    if (!recoveredMap[k]) {
      recovered_items.push({
        ...lastRow,
        _recovery: true,
      });

      // Marcamos que ya se notificó el recovery de este registro
      recoveredMap[k] = 1;
    }

    // Ya no está en alerta, lo quitamos del mapa de items en alerta
    delete prevItems[k];
  }
}

const send_recovery_partial = recovered_items.length > 0;

// 4) Transición informativa
let transition = `${last_state}->${state}`;

// 5) Salida (1 solo item) – este JSON es el que ven tus If
const ts_utc = new Date().toISOString();

return [
  {
    json: {
      instance_name: P.instance_name || "N/D",

      ts_utc,
      state,          // ALERT / OK
      last_state,
      transition,

      total: rows.length,
      alert_count: alerts.length,
      total_ok: oks.length,

      alerts,
      oks,
      recovered_items,

      send_alert,
      send_recovery_global,
      send_recovery_partial
    }
  }
];

