    const estado = r.Estado      || r.estado   || "Alerta: AutoGrowth";

    lines.push(`- **BD:** ${db}  •  **Archivo:** ${file}  •  Estado actual: ${estado}`);
  });
}

const text = `### ${title}\n\n` + lines.join("\n");

// Recuerda: el HTTP manda {{ $json.body }}
return [
  {
    json: {
      body: {
        text,
      },
    },
  },
];

// === Function – Decidir estado (AutoGrowth) con recovery por registro ===

const P = $node["Set - Params"].json || {};

// 1) Filas actuales: tomamos las que ya procesaste en "Function – Expand filas"
//    (ajusta el nombre si el nodo se llama distinto)
const rows = $items("Function – Expand filas").map(i => i.json);

// Helper: ¿esta fila está en ALERTA?
const isAlert = (r) => {
  const e = String(r.estado || r.Estado || "").toUpperCase();
  return e.startsWith("ALERTA");   // "Alerta: AutoGrowth"
};

// Clasificación actual
const alerts = rows.filter(isAlert);
const oks    = rows.filter(r => !isAlert(r));

// 2) Estado global en memoria (staticData), igual que en el flujo Cron origin:blue
const staticData = $getWorkflowStaticData('global');

const last_state = staticData.last_state || "INIT";       // ALERT / OK / INIT
const state      = alerts.length > 0 ? "ALERT" : "OK";

staticData.last_state = state;

// Flags globales
const send_alert           = alerts.length > 0;
const send_recovery_global = (last_state === "ALERT" && state === "OK");

// 3) Recovery por registro (BaseDeDatos + Archivo)

staticData.items     = staticData.items || {};     // registros en alerta última vez
staticData.recovered = staticData.recovered || {}; // registros ya notificados como recovery

const prevItems    = staticData.items;
const recoveredMap = staticData.recovered;

// Clave única de cada registro de AutoGrowth
const getKey = (r) => {
  const db   = r.BaseDeDatos || r.database || "";
  const file = r.Archivo     || r.file     || "";
  return `${db}|${file}`;
};

// Conjunto actual de registros en alerta
const currentAlertSet = {};

for (const r of alerts) {
  const k = getKey(r);
  if (!k) continue;

  // Marca que sigue en alerta en esta corrida
  currentAlertSet[k] = true;

  // Guardamos la última fila en alerta
  prevItems[k] = r;

  // Si ya lo habíamos marcado como recuperado y volvió a alerta, limpiamos
  if (recoveredMap[k]) {
    delete recoveredMap[k];
  }
}

// Registros que se recuperaron en esta corrida:
// estaban en prevItems y YA NO aparecen en currentAlertSet.
const recovered_items = [];

for (const [k, lastRow] of Object.entries(prevItems)) {
  if (!currentAlertSet[k]) {
    // Solo enviamos recovery si aún no lo habíamos enviado para este registro
    if (!recoveredMap[k]) {
      recovered_items.push({
        ...lastRow,
        _recovery: true,
      });

      // Marcamos que ya se notificó el recovery de este registro
      recoveredMap[k] = 1;
    }

    // Ya no está en alerta, lo quitamos del mapa de items en alerta
    delete prevItems[k];
  }
}

const send_recovery_partial = recovered_items.length > 0;

// 4) Transición informativa
let transition = `${last_state}->${state}`;

// 5) Salida (1 solo item) – este JSON es el que ven tus If
const ts_utc = new Date().toISOString();

return [
  {
    json: {
      instance_name: P.instance_name || "N/D",

      ts_utc,
      state,          // ALERT / OK
      last_state,
      transition,

      total: rows.length,
      alert_count: alerts.length,
      total_ok: oks.length,

      alerts,
      oks,
      recovered_items,

      send_alert,
      send_recovery_global,
      send_recovery_partial
    }
  }
];
